-- Longview, Gettysburg and Nashville GA: evidence read on the groups' own pages (2026-11-20), then published.
-- The own-site sentences replace the thin ones the cards carried
UPDATE "Club" SET "description" = 'Its own site says: "Mahj in the Pines is East Texas'' home for American Mahjong, offering beginner lessons, memberships, leagues, and social events in Longview, Marshall, Tyler, and throughout East Texas." Mahj on Tap evenings are open and guided play for players who know the basics and can follow the card.', "website" = 'https://mahjonginthepines.com', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'longview-mahj-in-the-pines';
UPDATE "Club" SET "description" = 'Its own page says: "Join us to play American Mahjong at the Gettysburg Library! This is a social play session for players who know the basics and want to enjoy the game and to practice and improve their skills in a non-competitive setting." Free; sign up through the group''s page.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'gettysburg-american-mahjong-at-gettysburg-library-open-play';

-- Teachers known only from a directory listing go back to review
UPDATE "Instructor" SET "status" = 'NEEDS_REVIEW', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" IN ('gettysburg-mah-jongg-class', 'longview-longview-mahj-club');

-- Publish with intros
UPDATE "City" SET "published" = 1, "intro" = 'Mahj in the Pines calls itself East Texas'' home for American Mahjong, with beginner lessons, memberships, leagues and social events in Longview, Marshall, Tyler and nearby towns. Its Mahj on Tap evenings are open and guided play at local restaurants and breweries for players who know the basics and can follow the card, and a monthly Sunday wine gathering is open too. Memberships include a current NMJL card. If you are new, start with one of its Mahj 101 classes.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'longview';
UPDATE "City" SET "published" = 1, "intro" = 'Gettysburg has a free library game and open play in the surrounding area. American Mahjong at Gettysburg Library Open Play is a social, non-competitive session for players who know the basics, and you sign up through the group''s page. Mahj Mojo runs open play evenings at tiki bar nights in Carlisle and a morning game in Mechanicsburg, and asks players to bring a 2026 NMJL card. If you are new, ask Mahj Mojo about its lessons, since both groups expect you to know the basics.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'gettysburg';
UPDATE "City" SET "published" = 1, "intro" = 'Nashville, Georgia has one regular game: Southern Sky Mah Jongg Social Club, which holds open play nights at a downtown venue on East Marion Avenue. Its page welcomes all skill levels, from brand-new beginners, and says lessons are available. Nights are ticketed from about $15, and a membership adds open play, lessons and a current NMJL card. Check the listing for the next date. If you are new, ask the club about a lesson before your first open play night.', "updatedAt" = CURRENT_TIMESTAMP WHERE "slug" = 'nashville-ga';
